/**
 * Brand assets and templates (R-231): only authorized brand asset kinds can be registered (logo, mascot,
 * decoration), with no option for a club badge or a competition mark; a registered asset is listed; the templates
 * keep their badge slots empty and show team and competition names as text. The image is a synthetic PNG generated by
 * the test (e2e/support/png.ts).
 */
import { solidPng } from '../support/png.js';
import { expect, test } from '../support/test.js';

const BADGE_WORDING = /escudo|insignia|emblema|badge|crest|marca de (la )?competici|club/i;

test.describe('Brand assets and templates (R-231)', () => {
  test('registering a brand asset offers no badge option; badge slots stay empty', async ({ page }) => {
    await page.goto('/brand');
    await expect(page.getByRole('heading', { level: 1, name: 'Marca y plantillas' })).toBeVisible();
    await expect(page.getByText(/No se registran escudos de clubes, marcas de competiciones/)).toBeVisible();

    const form = page.getByRole('form', { name: 'Registrar un recurso de marca' });
    const kinds = form.getByRole('group', { name: 'Tipo de recurso' }).getByRole('radio');
    await expect(kinds).toHaveCount(3);
    for (const [index, name] of ['Logotipo de la marca', 'Mascota', 'Decoración'].entries()) {
      await expect(kinds.nth(index)).toHaveAccessibleName(new RegExp(`^${name} `));
      await expect(kinds.nth(index)).not.toHaveAccessibleName(BADGE_WORDING);
    }
    await expect(form.getByRole('option')).toHaveCount(0);

    const label = 'Logotipo sintético de prueba';
    await kinds.nth(0).check();
    await form.getByRole('textbox', { name: 'Etiqueta' }).fill(label);
    await form.locator('input[type="file"]').setInputFiles({
      name: 'logotipo-sintetico.png',
      mimeType: 'image/png',
      buffer: solidPng(64, 64, [0x12, 0x5b, 0x3a]),
    });
    await form.getByRole('button', { name: 'Registrar recurso' }).click();
    await expect(page.getByRole('status', { name: 'Avisos de la página de marca' })).toHaveText(
      `Recurso «${label}» registrado.`,
    );
    const assets = page.getByRole('region', { name: 'Recursos registrados' });
    await expect(assets).toContainText(label);
    await expect(assets).toContainText('Logotipo de la marca');
    await expect(assets).not.toContainText(BADGE_WORDING);

    // Templates: the match-result template reserves badge slots that stay empty; no other template has any.
    const templates = page.getByRole('list', { name: 'Plantillas' });
    const matchResult = templates
      .getByRole('listitem')
      .filter({ has: page.getByRole('heading', { level: 3, name: 'Resultado de partido' }) });
    await expect(
      matchResult.locator('dt', { hasText: 'Espacios para escudos' }).locator('xpath=following-sibling::dd[1]'),
    ).toHaveText('2 espacios reservados; quedan vacíos porque no hay escudos autorizados.');
    for (const name of ['Portada', 'Tabla de posiciones', 'Cierre']) {
      const template = templates.getByRole('listitem').filter({ has: page.getByRole('heading', { level: 3, name }) });
      await expect(
        template.locator('dt', { hasText: 'Espacios para escudos' }).locator('xpath=following-sibling::dd[1]'),
      ).toHaveText('Ninguno');
    }
  });
});
